# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
        return out
    return out

# region: digest
def digest(xs, offset=1):
    return [v + offset for v in xs]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: render
def render(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return render(sift(digest(intake(gather(raw)))))

